            <?php
                // 最新 landscape の youtubeid / fvphoto を取得
                $args = [
                'post_type'      => 'landscape',
                'posts_per_page' => 1,
                'orderby'        => 'date',
                'order'          => 'DESC',
                ];
                $latest = get_posts($args);

                $youtube_id = '';
                $fvphoto_id = 0;    // 画像ID（優先）
                $fvphoto_url = '';  // 画像URL（IDが取れない時用）

                if ($latest) {
                $pid = $latest[0]->ID;

                // --- YouTube ID 取得
                if (function_exists('get_field')) {
                    $youtube_id = trim((string) get_field('youtubeid', $pid));
                } else {
                    $youtube_id = trim((string) get_post_meta($pid, 'youtubeid', true));
                }

                // URLが入ってきた場合はID抽出
                if ($youtube_id && strpos($youtube_id, 'http') === 0) {
                    if (preg_match('~(?:v=|youtu\.be/|embed/)([A-Za-z0-9_-]{6,64})~', $youtube_id, $m)) {
                    $youtube_id = $m[1];
                    }
                }

                // 不正な値は破棄
                if (!$youtube_id || !preg_match('/^[A-Za-z0-9_-]{6,64}$/', $youtube_id)) {
                    $youtube_id = '';
                }

                // --- fvphoto 取得（ACFの返り値どれでもOKにする）
                if (function_exists('get_field')) {
                    $fv = get_field('fvphoto', $pid);

                    if (is_array($fv)) {
                    // 返り値: 画像配列
                    if (!empty($fv['ID'])) {
                        $fvphoto_id = (int) $fv['ID'];
                    } elseif (!empty($fv['id'])) {
                        $fvphoto_id = (int) $fv['id'];
                    }
                    if (!$fvphoto_id && !empty($fv['url'])) {
                        $fvphoto_url = esc_url_raw($fv['url']);
                    }
                    } elseif (is_numeric($fv)) {
                    // 返り値: 画像ID
                    $fvphoto_id = (int) $fv;
                    } elseif (is_string($fv) && $fv !== '') {
                    // 返り値: 画像URL
                    $fvphoto_url = esc_url_raw($fv);
                    }
                } else {
                    // ACFなしの場合、メタキーが同名ならこちらで拾う
                    $maybe_id = get_post_meta($pid, 'fvphoto', true);
                    if (is_numeric($maybe_id)) {
                    $fvphoto_id = (int) $maybe_id;
                    } elseif (is_string($maybe_id) && $maybe_id !== '') {
                    $fvphoto_url = esc_url_raw($maybe_id);
                    }
                }
                }

                // 出力ロジック：YouTube優先 → 画像 → 最後にデフォ動画
                $default_youtube_id = 'yn0jfy9o72c'; //デフォルト動画youtubeID
            ?>

